create table if not exists public.calendar_state (user_id uuid primary key references auth.users(id) on delete cascade,events jsonb not null default '[]'::jsonb,categories jsonb not null default '{}'::jsonb,captures jsonb not null default '[]'::jsonb,larry jsonb not null default '{}'::jsonb,settings jsonb not null default '{}'::jsonb,notes text not null default '',user_quotes jsonb not null default '[]'::jsonb,filters jsonb not null default '[]'::jsonb,schema_version integer not null default 1,updated_at timestamptz not null default now());alter table public.calendar_state enable row level security;revoke all on table public.calendar_state from anon;grant select,insert,update,delete on table public.calendar_state to authenticated;drop policy if exists "calendar owners can read" on public.calendar_state;create policy "calendar owners can read" on public.calendar_state for select to authenticated using ((select auth.uid())=user_id);drop policy if exists "calendar owners can insert" on public.calendar_state;create policy "calendar owners can insert" on public.calendar_state for insert to authenticated with check ((select auth.uid())=user_id);drop policy if exists "calendar owners can update" on public.calendar_state;create policy "calendar owners can update" on public.calendar_state for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);drop policy if exists "calendar owners can delete" on public.calendar_state;create policy "calendar owners can delete" on public.calendar_state for delete to authenticated using ((select auth.uid())=user_id);create or replace function public.set_calendar_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end;$$;drop trigger if exists calendar_state_updated_at on public.calendar_state;create trigger calendar_state_updated_at before update on public.calendar_state for each row execute function public.set_calendar_updated_at();do $$ begin alter publication supabase_realtime add table public.calendar_state;exception when duplicate_object then null;end $$;